/**
 * Single source of truth per le pagine /sync/[provider] e /integrations.
 *
 * Ogni provider produce una landing SEO dedicata. Lo `status` determina
 * la CTA principale (download vs waitlist) e il badge mostrato.
 *
 * Quando una integrazione passa da `roadmap` o `beta` a `live`, basta
 * cambiare lo status qui e la landing si aggiorna automaticamente.
 */

import type { Locale } from "@/lib/i18n";

export type ProviderStatus =
  | "live" // Supportato nativamente (es. Galaxy Watch via Samsung Health → HC)
  | "live-basic" // Funziona oggi via Health Connect al livello base, OAuth ufficiale in arrivo per dati avanzati
  | "beta" // Implementato ma in test
  // P1.9 FASE 2 (2026-09-01): distinto da "beta" apposta — "beta" resta il
  // significato generico già in uso (oggi solo Suunto), questo copre un
  // caso diverso: capacità tecnica verificata (lettura funziona per chi è
  // già connesso) ma disponibilità dell'accesso stesso limitata da un
  // vincolo lato piattaforma esterna (revisione/approvazione in corso),
  // non da un bug o da funzionalità incompleta lato FitMesh. Introdotto per
  // Strava — vedi doc/seo/... e la nota nel provider stesso per il perché.
  | "limited-beta"
  | "roadmap-q3" // Pianificato Q3 2026 (NO path HC, serve OAuth)
  | "roadmap-q4" // Pianificato Q4 2026 (NO path HC, serve OAuth)
  | "coming-soon"; // In arrivo (data TBD — es. BLE diretto, feature sperimentali)

export type ProviderCategory =
  | "smartwatch"
  | "fitness-platform"
  | "health-platform"
  | "wearable"
  | "phone-only";

export interface ProviderFAQ {
  q: { it: string; en: string; es?: string; de?: string; pt?: string; fr?: string; pl?: string; tr?: string; nl?: string; ja?: string; ko?: string };
  a: { it: string; en: string; es?: string; de?: string; pt?: string; fr?: string; pl?: string; tr?: string; nl?: string; ja?: string; ko?: string };
}

/** Stringa localizzata sparsa (it/en obbligatorie, resto opzionale — stesso pattern del resto del file). */
type I18nStr = { it: string; en: string; es?: string; de?: string; pt?: string; fr?: string; pl?: string; tr?: string; nl?: string; ja?: string; ko?: string };
/** Lista localizzata sparsa. */
type I18nList = { it: string[]; en: string[]; es?: string[]; de?: string[]; pt?: string[]; fr?: string[]; pl?: string[]; tr?: string[]; nl?: string[]; ja?: string[]; ko?: string[] };

/**
 * FASE 5 P1.8C — nuovo modello editoriale delle landing, blocchi opzionali.
 * Ogni campo e' indipendentemente opzionale: una pagina che non li imposta
 * mantiene il rendering precedente, senza fallback inglesi nascosti o
 * sezioni vuote. Il rendering effettivo dei blocchi nuovi e' comunque
 * gated da `Provider.editorialTemplateV2` (vedi sotto) — pilotato solo su
 * pixel-watch e wear-os, non un rollout globale.
 */
export interface ProviderVerdict {
  /** "Funziona se..." — condizione reale, un paragrafo breve. */
  worksIf: I18nStr;
  /** "Probabilmente non ti serve se..." — chi non ha bisogno di FitMesh qui. */
  skipIf: I18nStr;
}
export interface ProviderSourcesBlock {
  /** Data di verifica ISO (es. "2026-08-25"), non localizzata. */
  verifiedOn: string;
  /**
   * Fonti visibili in pagina (non solo JSON-LD) — url raggiungibile 200.
   * Stesso formato/componente di `BlogPost.sources` (solo URL, mai un
   * titolo remoto non verificato): riusa `<BlogSources>`, non duplica la
   * logica di rendering.
   */
  sources: string[];
}

export interface Provider {
  /** URL slug — minuscolo, no spazi, no diacritici. Stabile (è SEO-critical). */
  slug: string;
  /** Nome commerciale completo (es. "Galaxy Watch", "Fitbit"). */
  name: string;
  /** Produttore (es. "Samsung", "Google"). */
  vendor: string;
  category: ProviderCategory;
  status: ProviderStatus;
  /**
   * Piattaforme FitMesh su cui questo provider è effettivamente leggibile.
   * Default (campo omesso) = `["android"]`, per compatibilità con i provider
   * esistenti (tutti Health Connect / Android-only). Va impostato esplicitamente
   * solo per i provider che divergono dal default: "apple-health" (`["ios"]`,
   * legge nativamente HealthKit) e "colmi-ring" (`["android", "ios"]`, BLE
   * diretto su entrambe le piattaforme). Guida operatingSystem/offers/store
   * link nel JSON-LD delle pagine /sync/[provider] — vedi quelle pagine.
   */
  platforms?: Array<"android" | "ios">;
  /**
   * Come i dati arrivano a FitMesh. Default (campo omesso) = "health-connect"
   * — vale per i 15 provider Android/Health-Connect esistenti. Va impostato
   * esplicitamente solo per i due che divergono: "colmi-ring" (BLE diretto,
   * niente Health Connect) e "apple-health" (HealthKit nativo iOS). Usato
   * dalle pagine /sync/[provider]/[model] per non mostrare copy "Health
   * Connect" generico su provider che non ci passano.
   */
  syncMechanism?: "health-connect" | "direct-ble" | "healthkit";
  /** Colore brand del provider (esadecimale). Usato per il monogramma badge. */
  brandColor: string;
  /** Lettera o emoji per il monogramma (no logo proprietario per ora). */
  initial: string;
  /** Tagline breve mostrata nelle card hub e nelle meta description. */
  tagline: { it: string; en: string; es?: string; de?: string; pt?: string; fr?: string; pl?: string; tr?: string; nl?: string; ja?: string; ko?: string };
  /** Long description per la landing (1-2 paragrafi). */
  longDesc: { it: string; en: string; es?: string; de?: string; pt?: string; fr?: string; pl?: string; tr?: string; nl?: string; ja?: string; ko?: string };
  /** Note tecniche sulla modalità di connessione (Health Connect / API diretta / etc.). */
  techNote: { it: string; en: string; es?: string; de?: string; pt?: string; fr?: string; pl?: string; tr?: string; nl?: string; ja?: string; ko?: string };
  /** Tipi di dato supportati o pianificati (mostrati come pill). */
  dataTypes: Array<{
    key: string;
    label: { it: string; en: string; es?: string; de?: string; pt?: string; fr?: string; pl?: string; tr?: string; nl?: string; ja?: string; ko?: string };
    supported: boolean;
    /**
     * MICRO-GATE P0.15-B (opzionale, additivo): se "conditional", la pill
     * rappresenta un dato che FitMesh sa leggere da Health Connect SE la
     * fonte lo scrive, ma nessuna fonte ufficiale conferma che questa
     * specifica fonte lo scriva davvero (il passo "C" della catena
     * A-misura/B-mostra/C-scrive su Health Connect/D-FitMesh legge — vedi
     * docs/seo/p015-oneplus-health-truth-ledger.md). La UI mostra un terzo
     * stato (ambra) invece del verde/grigio binario. Quando assente
     * (undefined, il default per gli altri 17 provider), `supported`
     * mantiene esattamente il significato e il rendering di sempre —
     * nessuna modifica retroattiva per chi non lo imposta.
     */
    status?: "conditional";
  }>;
  /** FAQ specifiche del provider (per JSON-LD FAQPage + render). */
  faqs: ProviderFAQ[];
  /** Keyword principali per il <meta description> e l'H1. */
  seoKeywords: { it: string[]; en: string[]; es?: string[]; de?: string[]; pt?: string[]; fr?: string[]; pl?: string[]; tr?: string[]; nl?: string[]; ja?: string[]; ko?: string[] };
  /**
   * Solo per status="live-basic": dettagli su cosa funziona oggi via Health Connect
   * e cosa aggiungerà l'integrazione OAuth ufficiale.
   */
  viaHC?: {
    /** ETA OAuth ufficiale (es. "Q3 2026"). */
    oauthEta: { it: string; en: string; es?: string; de?: string; pt?: string; fr?: string; pl?: string; tr?: string; nl?: string; ja?: string; ko?: string };
    /** Lista cose che funzionano già via HC (1 riga ognuna). */
    worksNow: { it: string[]; en: string[]; es?: string[]; de?: string[]; pt?: string[]; fr?: string[]; pl?: string[]; tr?: string[]; nl?: string[]; ja?: string[]; ko?: string[] };
    /** Lista cose che l'OAuth aggiungerà (1 riga ognuna). */
    oauthAdds: { it: string[]; en: string[]; es?: string[]; de?: string[]; pt?: string[]; fr?: string[]; pl?: string[]; tr?: string[]; nl?: string[]; ja?: string[]; ko?: string[] };
  };
  /** Guida step-by-step opzionale renderizzata tra tech note e FAQ. */
  setupGuide?: ProviderSetupGuide;
  /**
   * Slug di articoli blog correlati (renderizzati come card "Approfondisci"
   * in fondo alla landing). Internal linking SEO: distribuisce link equity
   * dalle landing /sync ai cornerstone /blog.
   */
  relatedBlogSlugs?: string[];

  // ── FASE 5 P1.8C: nuovo modello editoriale, pilota Pixel Watch/Wear OS ──
  /**
   * Opt-in esplicito al nuovo modello editoriale (verdetto, requisiti,
   * percorso dati, casi d'uso, limiti, fonti visibili, CTA dopo la
   * matrice dati). Omesso per i provider esistenti: nessun cambiamento di
   * rendering. Vedi FASE 5 del brief P1.8C — pilota, non rollout globale.
   */
  editorialTemplateV2?: boolean;
  /** Blocco 2: "funziona se... / non ti serve se...". */
  verdict?: ProviderVerdict;
  /** Blocco 3: requisiti minimi (bullet list). */
  requirements?: I18nList;
  /** Blocco 4: percorso dati — intro + passi ordinati "dove nasce -> dove passa -> dove arriva". */
  dataPath?: { intro: I18nStr; steps: I18nList };
  /** Blocco 6: casi d'uso concreti (bullet list), non generici. */
  useCases?: I18nList;
  /** Blocco 7: screenshot reale, mai un mock. Opzionale — nessun asset non equivale a placeholder. */
  screenshot?: { src: string; alt: I18nStr };
  /** Blocco 8: limiti onesti — cosa non arriva o non fa. */
  limitations?: I18nList;
  /** Blocco 12: fonti visibili + data di verifica. */
  sourcesBlock?: ProviderSourcesBlock;
}

export interface ProviderSetupGuide {
  /** Passi numerati (5 step ideale). Markdown bold inline OK via **text**. */
  steps: { it: string[]; en: string[]; es?: string[]; de?: string[]; pt?: string[]; fr?: string[]; pl?: string[]; tr?: string[]; nl?: string[]; ja?: string[]; ko?: string[] };
  /** Cosa viene sincronizzato (bullet list). */
  syncedData: { it: string[]; en: string[]; es?: string[]; de?: string[]; pt?: string[]; fr?: string[]; pl?: string[]; tr?: string[]; nl?: string[]; ja?: string[]; ko?: string[] };
  /** Troubleshooting Q&A (3 ideale). */
  troubleshooting: Array<{
    q: { it: string; en: string; es?: string; de?: string; pt?: string; fr?: string; pl?: string; tr?: string; nl?: string; ja?: string; ko?: string };
    a: { it: string; en: string; es?: string; de?: string; pt?: string; fr?: string; pl?: string; tr?: string; nl?: string; ja?: string; ko?: string };
  }>;
  /** Note tecniche conclusive (1 paragrafo). */
  technicalNotes: { it: string; en: string; es?: string; de?: string; pt?: string; fr?: string; pl?: string; tr?: string; nl?: string; ja?: string; ko?: string };
}

